    override fun compare(x: Pair, y: Pair): Int {
        return if (x.first < y.first || (x.first == y.first && x.second > y.second)) -1 else 1
    }
}

fun getGcd(a: Long, b: Long): Long {
    var aa = a
    var bb = b
    while (true) {
        if (bb == 0L) return aa
        val a1 = aa
        aa = bb
        bb = a1 % bb
    }
}

